try{const data=JSON.parse(localStorage.getItem('campusT-demo-v1'));if(data&&typeof data==='object'){state.wallet=data.wallet===true;state.progress=data.progress&&typeof data.progress==='object'?data.progress:{};state.custom=Array.isArray(data.custom)?data.custom.filter(e=>e&&typeof e.id==='string'&&typeof e.title==='string'&&['nft','token','both'].includes(e.reward)):[];state.school=['all','浙江大学','复旦大学','上海交通大学'].includes(data.school)?data.school:'all';}}catch{}
