function poster(e){return `<div class="poster ${escapeHTML(e.theme)}"><div class="poster-brand">${escapeHTML(e.brand)}</div><span class="status">${state.progress[e.id]==='claimed'?'已领取奖励':'报名进行中'}</span><div class="poster-title">${e.custom?'MAKE IT<br>HAPPEN.':e.poster}</div><span class="poster-caption">${escapeHTML(e.caption)}</span><div class="poster-shape" aria-hidden="true">${escapeHTML(e.shape)}</div></div>`;}
